package main

import (
	"database/sql"
	"sort"
	"strings"
	"sync"
	"time"
)

const (
	StMatching  = "MATCHING"
	StEnroute   = "ENROUTE"
	StPickup    = "PICKUP"
	StCarrying  = "CARRYING"
	StArrived   = "ARRIVED"
	StCompleted = "COMPLETED"
)

// mu guards every field reachable from st.
var mu sync.Mutex
var st *State

type Coupon struct {
	UserID    string
	Code      string
	Discount  int
	CreatedAt time.Time
	UsedBy    string
}

type RideStatus struct {
	Status    string
	CreatedAt time.Time
}

type Ride struct {
	ID         string
	User       *User
	Chair      *Chair
	PickupLat  int
	PickupLon  int
	DestLat    int
	DestLon    int
	Evaluation int // 0 = NULL
	CreatedAt  time.Time
	UpdatedAt  time.Time
	Statuses   []RideStatus
	Discount   int // discount of the coupon whose used_by is this ride
	paying     bool
}

func (r *Ride) Latest() string {
	return r.Statuses[len(r.Statuses)-1].Status
}

func (r *Ride) hasStatus(s string) bool {
	for _, x := range r.Statuses {
		if x.Status == s {
			return true
		}
	}
	return false
}

func (r *Ride) Fare() int {
	metered := farePerDistance * calculateDistance(r.PickupLat, r.PickupLon, r.DestLat, r.DestLon)
	return initialFare + max(metered-r.Discount, 0)
}

func (r *Ride) RawFare() int {
	return calculateFare(r.PickupLat, r.PickupLon, r.DestLat, r.DestLon)
}

type User struct {
	ID             string
	Username       string
	Firstname      string
	Lastname       string
	DateOfBirth    string
	AccessToken    string
	InvitationCode string
	CreatedAt      time.Time
	Rides          []*Ride   // created_at asc
	Coupons        []*Coupon // created_at asc
	PaymentToken   string
	HasToken       bool
	notif          *Notifier
}

func (u *User) LatestRide() *Ride {
	if len(u.Rides) == 0 {
		return nil
	}
	return u.Rides[len(u.Rides)-1]
}

type Owner struct {
	ID                 string
	Name               string
	AccessToken        string
	ChairRegisterToken string
	CreatedAt          time.Time
	Chairs             []*Chair // id asc
}

type Chair struct {
	ID          string
	Owner       *Owner
	Name        string
	Model       string
	Speed       int
	IsActive    bool
	AccessToken string
	CreatedAt   time.Time
	UpdatedAt   time.Time

	HasLoc    bool
	Lat       int
	Lon       int
	LocAt     time.Time
	TotalDist int

	Rides     []*Ride // all rides assigned to this chair
	Current   *Ride   // latest ride by updated_at
	Delivered bool    // COMPLETED of Current has been delivered to the chair

	StatCount   int
	StatEvalSum int

	notif *Notifier
}

type State struct {
	PaymentURL string
	Models     map[string]int

	Users        map[string]*User
	UsersByToken map[string]*User
	UsersByInv   map[string]*User
	UsersByName  map[string]*User
	InvUsed      map[string]int // invitation code -> number of times used

	Owners        map[string]*Owner
	OwnersByToken map[string]*Owner
	OwnersByReg   map[string]*Owner
	OwnersByName  map[string]*Owner

	Chairs        map[string]*Chair
	ChairsByToken map[string]*Chair
	ChairList     []*Chair // id asc

	Rides   map[string]*Ride
	Waiting []*Ride // rides without chair, created order
}

func newState() *State {
	return &State{
		Models:        map[string]int{},
		Users:         map[string]*User{},
		UsersByToken:  map[string]*User{},
		UsersByInv:    map[string]*User{},
		UsersByName:   map[string]*User{},
		InvUsed:       map[string]int{},
		Owners:        map[string]*Owner{},
		OwnersByToken: map[string]*Owner{},
		OwnersByReg:   map[string]*Owner{},
		OwnersByName:  map[string]*Owner{},
		Chairs:        map[string]*Chair{},
		ChairsByToken: map[string]*Chair{},
		Rides:         map[string]*Ride{},
	}
}

func loadState(db *sql.DB) (*State, error) {
	s := newState()

	if err := db.QueryRow("SELECT value FROM settings WHERE name = 'payment_gateway_url'").Scan(&s.PaymentURL); err != nil && err != sql.ErrNoRows {
		return nil, err
	}

	rows, err := db.Query("SELECT name, speed FROM chair_models")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var n string
		var sp int
		if err := rows.Scan(&n, &sp); err != nil {
			rows.Close()
			return nil, err
		}
		s.Models[n] = sp
	}
	rows.Close()

	rows, err = db.Query("SELECT id, name, access_token, chair_register_token, created_at FROM owners ORDER BY id")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		o := &Owner{}
		if err := rows.Scan(&o.ID, &o.Name, &o.AccessToken, &o.ChairRegisterToken, &o.CreatedAt); err != nil {
			rows.Close()
			return nil, err
		}
		s.Owners[o.ID] = o
		s.OwnersByToken[o.AccessToken] = o
		s.OwnersByReg[o.ChairRegisterToken] = o
		s.OwnersByName[o.Name] = o
	}
	rows.Close()

	rows, err = db.Query("SELECT id, owner_id, name, model, is_active, access_token, created_at, updated_at FROM chairs ORDER BY id")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		c := &Chair{Delivered: true}
		var ownerID string
		if err := rows.Scan(&c.ID, &ownerID, &c.Name, &c.Model, &c.IsActive, &c.AccessToken, &c.CreatedAt, &c.UpdatedAt); err != nil {
			rows.Close()
			return nil, err
		}
		c.Owner = s.Owners[ownerID]
		c.Speed = s.speedOf(c.Model)
		c.notif = newNotifier()
		s.Chairs[c.ID] = c
		s.ChairsByToken[c.AccessToken] = c
		s.ChairList = append(s.ChairList, c)
		if c.Owner != nil {
			c.Owner.Chairs = append(c.Owner.Chairs, c)
		}
	}
	rows.Close()

	rows, err = db.Query("SELECT chair_id, latitude, longitude, created_at FROM chair_locations ORDER BY chair_id, created_at")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var cid string
		var lat, lon int
		var t time.Time
		if err := rows.Scan(&cid, &lat, &lon, &t); err != nil {
			rows.Close()
			return nil, err
		}
		c := s.Chairs[cid]
		if c == nil {
			continue
		}
		if c.HasLoc {
			c.TotalDist += abs(lat-c.Lat) + abs(lon-c.Lon)
		}
		c.HasLoc = true
		c.Lat, c.Lon, c.LocAt = lat, lon, t
	}
	rows.Close()

	rows, err = db.Query("SELECT id, username, firstname, lastname, date_of_birth, access_token, invitation_code, created_at FROM users")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		u := &User{}
		if err := rows.Scan(&u.ID, &u.Username, &u.Firstname, &u.Lastname, &u.DateOfBirth, &u.AccessToken, &u.InvitationCode, &u.CreatedAt); err != nil {
			rows.Close()
			return nil, err
		}
		u.notif = newNotifier()
		s.Users[u.ID] = u
		s.UsersByToken[u.AccessToken] = u
		s.UsersByInv[u.InvitationCode] = u
		s.UsersByName[u.Username] = u
	}
	rows.Close()

	rows, err = db.Query("SELECT user_id, token FROM payment_tokens")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var uid, tok string
		if err := rows.Scan(&uid, &tok); err != nil {
			rows.Close()
			return nil, err
		}
		if u := s.Users[uid]; u != nil {
			u.PaymentToken = tok
			u.HasToken = true
		}
	}
	rows.Close()

	rows, err = db.Query("SELECT id, user_id, chair_id, pickup_latitude, pickup_longitude, destination_latitude, destination_longitude, evaluation, created_at, updated_at FROM rides ORDER BY created_at, id")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		r := &Ride{}
		var uid string
		var cid sql.NullString
		var ev sql.NullInt64
		if err := rows.Scan(&r.ID, &uid, &cid, &r.PickupLat, &r.PickupLon, &r.DestLat, &r.DestLon, &ev, &r.CreatedAt, &r.UpdatedAt); err != nil {
			rows.Close()
			return nil, err
		}
		if ev.Valid {
