		if r.User == nil {
			continue
		}
		if cid.Valid {
			r.Chair = s.Chairs[cid.String]
		}
		s.Rides[r.ID] = r
		r.User.Rides = append(r.User.Rides, r)
		if r.Chair != nil {
			r.Chair.Rides = append(r.Chair.Rides, r)
		}
	}
	rows.Close()

	rows, err = db.Query("SELECT ride_id, status, created_at FROM ride_statuses ORDER BY ride_id, created_at, id")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var rid string
		var rs RideStatus
		if err := rows.Scan(&rid, &rs.Status, &rs.CreatedAt); err != nil {
			rows.Close()
			return nil, err
		}
		if r := s.Rides[rid]; r != nil {
			r.Statuses = append(r.Statuses, rs)
		}
	}
	rows.Close()

	rows, err = db.Query("SELECT user_id, code, discount, created_at, used_by FROM coupons ORDER BY created_at, code")
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		c := &Coupon{}
		var usedBy sql.NullString
		if err := rows.Scan(&c.UserID, &c.Code, &c.Discount, &c.CreatedAt, &usedBy); err != nil {
			rows.Close()
			return nil, err
		}
		if usedBy.Valid {
			c.UsedBy = usedBy.String
			if r := s.Rides[c.UsedBy]; r != nil {
				r.Discount = c.Discount
			}
		}
		if strings.HasPrefix(c.Code, "INV_") {
			s.InvUsed[c.Code[4:]]++
		}
		if u := s.Users[c.UserID]; u != nil {
			u.Coupons = append(u.Coupons, c)
		}
	}
	rows.Close()

	// derived data
	for _, r := range s.Rides {
		if len(r.Statuses) == 0 {
			// should not happen; treat as MATCHING
			r.Statuses = append(r.Statuses, RideStatus{Status: StMatching, CreatedAt: r.CreatedAt})
		}
		if r.Chair == nil {
			s.Waiting = append(s.Waiting, r)
		}
	}
	sort.Slice(s.Waiting, func(i, j int) bool { return s.Waiting[i].CreatedAt.Before(s.Waiting[j].CreatedAt) })
	for _, c := range s.ChairList {
		for _, r := range c.Rides {
			if c.Current == nil || r.UpdatedAt.After(c.Current.UpdatedAt) {
				c.Current = r
			}
			if r.Latest() == StCompleted && r.hasStatus(StArrived) && r.hasStatus(StCarrying) {
				c.StatCount++
				c.StatEvalSum += r.Evaluation
			}
		}
	}
	return s, nil
}

func (s *State) speedOf(model string) int {
	if sp, ok := s.Models[model]; ok && sp > 0 {
		return sp
	}
	return 1
}

