const (
	StMatching  = "MATCHING"
	StEnroute   = "ENROUTE"
	StPickup    = "PICKUP"
	StCarrying  = "CARRYING"
	StArrived   = "ARRIVED"
	StCompleted = "COMPLETED"
)

// mu guards every field reachable from st.
var mu sync.Mutex
var st *State

type Coupon struct {
	UserID    string
	Code      string
	Discount  int
	CreatedAt time.Time
	UsedBy    string
}

type RideStatus struct {
	Status    string
	CreatedAt time.Time
}

type Ride struct {
	ID         string
	User       *User
	Chair      *Chair
	PickupLat  int
	PickupLon  int
	DestLat    int
	DestLon    int
	Evaluation int // 0 = NULL
	CreatedAt  time.Time
	UpdatedAt  time.Time
	Statuses   []RideStatus
	Discount   int // discount of the coupon whose used_by is this ride
	paying     bool
}

func (r *Ride) Latest() string {
	return r.Statuses[len(r.Statuses)-1].Status
}

func (r *Ride) hasStatus(s string) bool {
	for _, x := range r.Statuses {
		if x.Status == s {
			return true
		}
	}
	return false
}

func (r *Ride) Fare() int {
	metered := farePerDistance * calculateDistance(r.PickupLat, r.PickupLon, r.DestLat, r.DestLon)
	return initialFare + max(metered-r.Discount, 0)
}

func (r *Ride) RawFare() int {
	return calculateFare(r.PickupLat, r.PickupLon, r.DestLat, r.DestLon)
}

