	ID             string
	Username       string
	Firstname      string
	Lastname       string
	DateOfBirth    string
	AccessToken    string
	InvitationCode string
	CreatedAt      time.Time
	Rides          []*Ride   // created_at asc
	Coupons        []*Coupon // created_at asc
