	OwnersByToken map[string]*Owner
	OwnersByReg   map[string]*Owner
	OwnersByName  map[string]*Owner

	Chairs        map[string]*Chair
	ChairsByToken map[string]*Chair
	ChairList     []*Chair // id asc

	Rides   map[string]*Ride
	Waiting []*Ride // rides without chair, created order
