package main

import (
	"database/sql"
	"log"
	"strings"
	"sync"
	"time"
)

// Write-behind persistence. All in-memory mutations are mirrored to MySQL
// asynchronously, preserving order within the general queue.

type dbOp struct {
	q    string
	args []any
}

type locRow struct {
	id      string
	chairID string
	lat     int
	lon     int
	t       time.Time
}

var (
	qmu      sync.Mutex
	opQueue  []dbOp
	locQueue []locRow
	qsig     = make(chan struct{}, 1)
	writerMu sync.Mutex // held while a batch is being written; initialize takes it
)

func persist(q string, args ...any) {
	qmu.Lock()
	opQueue = append(opQueue, dbOp{q, args})
	qmu.Unlock()
	select {
	case qsig <- struct{}{}:
	default:
	}
}

func persistLoc(id, chairID string, lat, lon int, t time.Time) {
	qmu.Lock()
	locQueue = append(locQueue, locRow{id, chairID, lat, lon, t})
	qmu.Unlock()
}

// discardQueues drops everything pending. Caller must hold writerMu.
func discardQueues() {
	qmu.Lock()
	opQueue = nil
	locQueue = nil
	qmu.Unlock()
}

func writerLoop() {
	t := time.NewTicker(200 * time.Millisecond)
	defer t.Stop()
	for {
		select {
		case <-qsig:
		case <-t.C:
		}
		flushOnce()
	}
}

func flushOnce() {
	writerMu.Lock()
	defer writerMu.Unlock()
	qmu.Lock()
	ops := opQueue
	locs := locQueue
	opQueue = nil
	locQueue = nil
	qmu.Unlock()

	for len(ops) > 0 {
		n := min(len(ops), 300)
		execBatch(ops[:n])
		ops = ops[n:]
	}
	for len(locs) > 0 {
		n := min(len(locs), 2000)
		insertLocs(locs[:n])
		locs = locs[n:]
	}
}

func execBatch(ops []dbOp) {
	tx, err := db.Begin()
	if err != nil {
		log.Printf("persist begin: %v", err)
		return
	}
	for _, op := range ops {
		if _, err := tx.Exec(op.q, op.args...); err != nil {
			log.Printf("persist exec %q: %v", op.q, err)
		}
	}
	if err := tx.Commit(); err != nil {
		log.Printf("persist commit: %v", err)
	}
}

func insertLocs(locs []locRow) {
	var sb strings.Builder
	sb.WriteString("INSERT INTO chair_locations (id, chair_id, latitude, longitude, created_at) VALUES ")
	args := make([]any, 0, len(locs)*5)
	for i, l := range locs {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString("(?,?,?,?,?)")
		args = append(args, l.id, l.chairID, l.lat, l.lon, l.t)
	}
	if _, err := db.Exec(sb.String(), args...); err != nil {
		log.Printf("persist locs: %v", err)
	}
}

var _ = sql.ErrNoRows

