package main

import (
	"encoding/json"
	"net/http"
	"time"
)

// Event is a serialized notification payload.
type Event struct {
	data   []byte
	rideID string
	status string
}

// Notifier holds events that have not been confirmed delivered yet, in order.
// A newer SSE connection supersedes older ones (gen).
type Notifier struct {
	pending []Event
	ch      chan struct{}
	gen     int
}

func newNotifier() *Notifier {
	return &Notifier{ch: make(chan struct{}, 1)}
}

func (n *Notifier) signal() {
	select {
	case n.ch <- struct{}{}:
	default:
	}
}

// push must be called with mu held.
func (n *Notifier) push(e Event) {
	n.pending = append(n.pending, e)
	n.signal()
}

type coordJSON struct {
	Latitude  int `json:"latitude"`
	Longitude int `json:"longitude"`
}

type userNotifChairStats struct {
	TotalRidesCount    int     `json:"total_rides_count"`
	TotalEvaluationAvg float64 `json:"total_evaluation_avg"`
}

type userNotifChair struct {
	ID    string              `json:"id"`
	Name  string              `json:"name"`
	Model string              `json:"model"`
	Stats userNotifChairStats `json:"stats"`
}

type userNotifData struct {
	RideID                string          `json:"ride_id"`
	PickupCoordinate      coordJSON       `json:"pickup_coordinate"`
	DestinationCoordinate coordJSON       `json:"destination_coordinate"`
	Fare                  int             `json:"fare"`
	Status                string          `json:"status"`
	Chair                 *userNotifChair `json:"chair,omitempty"`
	CreatedAt             int64           `json:"created_at"`
	UpdateAt              int64           `json:"updated_at"`
}

type simpleUser struct {
	ID   string `json:"id"`
	Name string `json:"name"`
}

type chairNotifData struct {
	RideID                string     `json:"ride_id"`
	User                  simpleUser `json:"user"`
	PickupCoordinate      coordJSON  `json:"pickup_coordinate"`
	DestinationCoordinate coordJSON  `json:"destination_coordinate"`
	Status                string     `json:"status"`
}

func chairStats(c *Chair) userNotifChairStats {
	s := userNotifChairStats{TotalRidesCount: c.StatCount}
	if c.StatCount > 0 {
		s.TotalEvaluationAvg = float64(c.StatEvalSum) / float64(c.StatCount)
	}
	return s
}

// userEvent must be called with mu held.
func userEvent(r *Ride, status string) Event {
	d := userNotifData{
		RideID:                r.ID,
		PickupCoordinate:      coordJSON{r.PickupLat, r.PickupLon},
		DestinationCoordinate: coordJSON{r.DestLat, r.DestLon},
		Fare:                  r.Fare(),
		Status:                status,
