package main

import (
	"sort"
	"time"
)

var matchSig = make(chan struct{}, 1)

func triggerMatch() {
	select {
	case matchSig <- struct{}{}:
	default:
	}
}

const (
	matchInterval = 100 * time.Millisecond
	urgentWait    = 10 * time.Second
	maxNormalDist = 400
)

func matcherLoop() {
	t := time.NewTicker(matchInterval)
	defer t.Stop()
	for {
		select {
		case <-t.C:
		case <-matchSig:
		}
		mu.Lock()
		if st != nil {
			st.match(time.Now())
		}
		mu.Unlock()
	}
}

func (c *Chair) isFree() bool {
	if !c.IsActive || !c.HasLoc {
		return false
	}
	if c.Current == nil {
		return true
	}
	return c.Current.Latest() == StCompleted && c.Delivered
}

type matchPair struct {
	ri, ci int
	cost   float64
}

// match assigns free chairs to waiting rides. mu held.
func (s *State) match(now time.Time) {
	if len(s.Waiting) == 0 {
		return
	}
	free := make([]*Chair, 0, 64)
	for _, c := range s.ChairList {
		if c.isFree() {
			free = append(free, c)
		}
	}
	if len(free) == 0 {
		return
	}
	rides := s.Waiting
	usedR := make([]bool, len(rides))
	usedC := make([]bool, len(free))
	cost := func(r *Ride, c *Chair) float64 {
		d := calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
		return float64(d) / float64(c.Speed)
	}

	assigned := 0
	// urgent rides first: oldest first, best chair regardless of distance
	for ri, r := range rides {
		if now.Sub(r.CreatedAt) < urgentWait {
			break
		}
		best := -1
		bestCost := 0.0
		for ci, c := range free {
			if usedC[ci] {
				continue
			}
			cc := cost(r, c)
			if best < 0 || cc < bestCost {
				best, bestCost = ci, cc
			}
		}
		if best < 0 {
			break
		}
		usedR[ri], usedC[best] = true, true
		s.assign(r, free[best], now)
		assigned++
	}

	if assigned < len(free) {
		pairs := make([]matchPair, 0, len(rides)*len(free))
		for ri, r := range rides {
			if usedR[ri] {
				continue
			}
			for ci, c := range free {
				if usedC[ci] {
					continue
				}
				d := calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
				if d > maxNormalDist {
					continue
				}
				pairs = append(pairs, matchPair{ri, ci, float64(d) / float64(c.Speed)})
			}
		}
		sort.Slice(pairs, func(i, j int) bool {
			if pairs[i].cost != pairs[j].cost {
				return pairs[i].cost < pairs[j].cost
			}
			return pairs[i].ri < pairs[j].ri
		})
		for _, p := range pairs {
			if usedR[p.ri] || usedC[p.ci] {
				continue
			}
			usedR[p.ri], usedC[p.ci] = true, true
			s.assign(rides[p.ri], free[p.ci], now)
			assigned++
		}
	}

	if assigned > 0 {
		rest := make([]*Ride, 0, len(rides)-assigned)
		for ri, r := range rides {
			if !usedR[ri] {
				rest = append(rest, r)
			}
		}
		s.Waiting = rest
	}
}

func (s *State) assign(r *Ride, c *Chair, now time.Time) {
	r.Chair = c
	r.UpdatedAt = now
	c.Current = r
	c.Delivered = false
	c.Rides = append(c.Rides, r)
	persist("UPDATE rides SET chair_id = ?, updated_at = ? WHERE id = ?", c.ID, now, r.ID)
	c.notif.push(chairEvent(r, StMatching))
}

