package main

import (
	crand "crypto/rand"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	_ "net/http/pprof"
	"os"
	"os/exec"
	"strconv"
	"time"

	"github.com/go-sql-driver/mysql"
	"github.com/oklog/ulid/v2"
)

const (
	initialFare     = 500
	farePerDistance = 100
)

var db *sql.DB

func getenv(k, def string) string {
	if v := os.Getenv(k); v != "" {
		return v
	}
	return def
}

func main() {
	host := getenv("ISUCON_DB_HOST", "127.0.0.1")
	port := getenv("ISUCON_DB_PORT", "3306")
	if _, err := strconv.Atoi(port); err != nil {
		panic(fmt.Sprintf("failed to convert DB port number from ISUCON_DB_PORT environment variable into int: %v", err))
	}
	cfg := mysql.NewConfig()
	cfg.User = getenv("ISUCON_DB_USER", "isucon")
	cfg.Passwd = getenv("ISUCON_DB_PASSWORD", "isucon")
	cfg.Addr = net.JoinHostPort(host, port)
	cfg.Net = "tcp"
	cfg.DBName = getenv("ISUCON_DB_NAME", "isuride")
	cfg.ParseTime = true
	cfg.Loc = time.UTC
	cfg.InterpolateParams = true

	var err error
	db, err = sql.Open("mysql", cfg.FormatDSN())
	if err != nil {
		panic(err)
	}
	db.SetMaxOpenConns(8)
	db.SetMaxIdleConns(8)
	db.SetConnMaxLifetime(0)

	// Wait for the DB (it may live on another host that is still booting).
	for i := 0; ; i++ {
		s, err := loadState(db)
		if err == nil {
			mu.Lock()
			st = s
			mu.Unlock()
			break
		}
		log.Printf("loadState failed (attempt %d): %v", i, err)
		time.Sleep(2 * time.Second)
	}
	log.Printf("state loaded: users=%d chairs=%d rides=%d", len(st.Users), len(st.Chairs), len(st.Rides))

	go writerLoop()
	go matcherLoop()
	go func() {
		log.Println(http.ListenAndServe("127.0.0.1:6060", nil))
	}()

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/initialize", postInitialize)

	mux.HandleFunc("POST /api/app/users", appPostUsers)
	mux.HandleFunc("POST /api/app/payment-methods", withUser(appPostPaymentMethods))
	mux.HandleFunc("GET /api/app/rides", withUser(appGetRides))
	mux.HandleFunc("POST /api/app/rides", withUser(appPostRides))
	mux.HandleFunc("POST /api/app/rides/estimated-fare", withUser(appPostRidesEstimatedFare))
	mux.HandleFunc("POST /api/app/rides/{ride_id}/evaluation", withUser(appPostRideEvaluation))
	mux.HandleFunc("GET /api/app/notification", withUser(appGetNotification))
	mux.HandleFunc("GET /api/app/nearby-chairs", withUser(appGetNearbyChairs))

	mux.HandleFunc("POST /api/owner/owners", ownerPostOwners)
	mux.HandleFunc("GET /api/owner/sales", withOwner(ownerGetSales))
	mux.HandleFunc("GET /api/owner/chairs", withOwner(ownerGetChairs))

	mux.HandleFunc("POST /api/chair/chairs", chairPostChairs)
	mux.HandleFunc("POST /api/chair/activity", withChair(chairPostActivity))
	mux.HandleFunc("POST /api/chair/coordinate", withChair(chairPostCoordinate))
	mux.HandleFunc("GET /api/chair/notification", withChair(chairGetNotification))
