package main

import (
	"errors"
	"net/http"
	"strconv"
	"time"
)

type appPostUsersRequest struct {
	Username       string  `json:"username"`
	FirstName      string  `json:"firstname"`
	LastName       string  `json:"lastname"`
	DateOfBirth    string  `json:"date_of_birth"`
	InvitationCode *string `json:"invitation_code"`
}

type appPostUsersResponse struct {
	ID             string `json:"id"`
	InvitationCode string `json:"invitation_code"`
}

func appPostUsers(w http.ResponseWriter, r *http.Request) {
	req := &appPostUsersRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Username == "" || req.FirstName == "" || req.LastName == "" || req.DateOfBirth == "" {
		writeError(w, http.StatusBadRequest, errors.New("required fields(username, firstname, lastname, date_of_birth) are empty"))
		return
	}

	userID := newID()
	accessToken := secureRandomStr(32)
	invitationCode := secureRandomStr(15)

	mu.Lock()
	s := st
	if _, dup := s.UsersByName[req.Username]; dup {
		mu.Unlock()
		writeError(w, http.StatusInternalServerError, errors.New("Error 1062 (23000): Duplicate entry for key 'users.username'"))
		return
	}
	var inviter *User
	invCode := ""
	if req.InvitationCode != nil && *req.InvitationCode != "" {
		invCode = *req.InvitationCode
		if s.InvUsed[invCode] >= 3 {
			mu.Unlock()
			writeError(w, http.StatusBadRequest, errors.New("この招待コードは使用できません。"))
			return
		}
		inviter = s.UsersByInv[invCode]
		if inviter == nil {
			mu.Unlock()
			writeError(w, http.StatusBadRequest, errors.New("この招待コードは使用できません。"))
			return
		}
	}

	now := nowUS()
	u := &User{
		ID:             userID,
		Username:       req.Username,
		Firstname:      req.FirstName,
		Lastname:       req.LastName,
		DateOfBirth:    req.DateOfBirth,
		AccessToken:    accessToken,
		InvitationCode: invitationCode,
		CreatedAt:      now,
		notif:          newNotifier(),
	}
	s.Users[u.ID] = u
	s.UsersByToken[u.AccessToken] = u
	s.UsersByInv[u.InvitationCode] = u
	s.UsersByName[u.Username] = u
	persist("INSERT INTO users (id, username, firstname, lastname, date_of_birth, access_token, invitation_code, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
		u.ID, u.Username, u.Firstname, u.Lastname, u.DateOfBirth, u.AccessToken, u.InvitationCode, now, now)

	addCoupon(u, "CP_NEW2024", 3000, now)
	if inviter != nil {
		s.InvUsed[invCode]++
		addCoupon(u, "INV_"+invCode, 1500, now.Add(time.Microsecond))
		t := now.Add(2 * time.Microsecond)
		addCoupon(inviter, "RWD_"+invCode+"_"+strconv.FormatInt(t.UnixMilli(), 10)+"_"+userID[16:], 1000, t)
	}
	mu.Unlock()

	http.SetCookie(w, &http.Cookie{Path: "/", Name: "app_session", Value: accessToken})
	writeJSON(w, http.StatusCreated, &appPostUsersResponse{ID: userID, InvitationCode: invitationCode})
}

// addCoupon mu held.
func addCoupon(u *User, code string, discount int, t time.Time) {
	c := &Coupon{UserID: u.ID, Code: code, Discount: discount, CreatedAt: t}
	u.Coupons = append(u.Coupons, c)
	persist("INSERT INTO coupons (user_id, code, discount, created_at) VALUES (?, ?, ?, ?)", u.ID, code, discount, t)
}

type appPostPaymentMethodsRequest struct {
	Token string `json:"token"`
}

func appPostPaymentMethods(w http.ResponseWriter, r *http.Request, u *User) {
	req := &appPostPaymentMethodsRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Token == "" {
		writeError(w, http.StatusBadRequest, errors.New("token is required but was empty"))
		return
	}
	mu.Lock()
	if u.HasToken {
		mu.Unlock()
		writeError(w, http.StatusInternalServerError, errors.New("Error 1062 (23000): Duplicate entry for key 'payment_tokens.PRIMARY'"))
		return
	}
	u.PaymentToken = req.Token
	u.HasToken = true
	persist("INSERT INTO payment_tokens (user_id, token, created_at) VALUES (?, ?, ?)", u.ID, req.Token, nowUS())
	mu.Unlock()
	w.WriteHeader(http.StatusNoContent)
}

type getAppRidesResponse struct {
	Rides []getAppRidesResponseItem `json:"rides"`
}

type getAppRidesResponseItem struct {
	ID                    string                       `json:"id"`
	PickupCoordinate      Coordinate                   `json:"pickup_coordinate"`
	DestinationCoordinate Coordinate                   `json:"destination_coordinate"`
	Chair                 getAppRidesResponseItemChair `json:"chair"`
	Fare                  int                          `json:"fare"`
	Evaluation            int                          `json:"evaluation"`
	RequestedAt           int64                        `json:"requested_at"`
	CompletedAt           int64                        `json:"completed_at"`
}

type getAppRidesResponseItemChair struct {
	ID    string `json:"id"`
	Owner string `json:"owner"`
	Name  string `json:"name"`
	Model string `json:"model"`
}

func appGetRides(w http.ResponseWriter, r *http.Request, u *User) {
	items := []getAppRidesResponseItem{}
	mu.Lock()
	for i := len(u.Rides) - 1; i >= 0; i-- {
		ride := u.Rides[i]
		if ride.Latest() != StCompleted {
			continue
		}
		item := getAppRidesResponseItem{
			ID:                    ride.ID,
			PickupCoordinate:      Coordinate{Latitude: ride.PickupLat, Longitude: ride.PickupLon},
			DestinationCoordinate: Coordinate{Latitude: ride.DestLat, Longitude: ride.DestLon},
			Fare:                  ride.Fare(),
			Evaluation:            ride.Evaluation,
			RequestedAt:           ride.CreatedAt.UnixMilli(),
			CompletedAt:           ride.UpdatedAt.UnixMilli(),
		}
		if c := ride.Chair; c != nil {
			item.Chair.ID = c.ID
			item.Chair.Name = c.Name
			item.Chair.Model = c.Model
			if c.Owner != nil {
				item.Chair.Owner = c.Owner.Name
			}
		}
		items = append(items, item)
	}
	mu.Unlock()
	writeJSON(w, http.StatusOK, &getAppRidesResponse{Rides: items})
}

type appPostRidesRequest struct {
	PickupCoordinate      *Coordinate `json:"pickup_coordinate"`
	DestinationCoordinate *Coordinate `json:"destination_coordinate"`
}

type appPostRidesResponse struct {
	RideID string `json:"ride_id"`
	Fare   int    `json:"fare"`
}

func appPostRides(w http.ResponseWriter, r *http.Request, u *User) {
	req := &appPostRidesRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.PickupCoordinate == nil || req.DestinationCoordinate == nil {
		writeError(w, http.StatusBadRequest, errors.New("required fields(pickup_coordinate, destination_coordinate) are empty"))
		return
	}
	rideID := newID()

	mu.Lock()
	s := st
	for _, ride := range u.Rides {
		if ride.Latest() != StCompleted {
			mu.Unlock()
			writeError(w, http.StatusConflict, errors.New("ride already exists"))
			return
		}
	}
	now := nowUS()
	ride := &Ride{
		ID:        rideID,
		User:      u,
		PickupLat: req.PickupCoordinate.Latitude,
		PickupLon: req.PickupCoordinate.Longitude,
		DestLat:   req.DestinationCoordinate.Latitude,
		DestLon:   req.DestinationCoordinate.Longitude,
		CreatedAt: now,
		UpdatedAt: now,
	}
	u.Rides = append(u.Rides, ride)
	s.Rides[ride.ID] = ride
	persist("INSERT INTO rides (id, user_id, pickup_latitude, pickup_longitude, destination_latitude, destination_longitude, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
		ride.ID, u.ID, ride.PickupLat, ride.PickupLon, ride.DestLat, ride.DestLon, now, now)

	// coupon
	var coupon *Coupon
	if len(u.Rides) == 1 {
		for _, c := range u.Coupons {
			if c.Code == "CP_NEW2024" && c.UsedBy == "" {
				coupon = c
				break
			}
		}
	}
	if coupon == nil {
		for _, c := range u.Coupons {
			if c.UsedBy == "" {
				coupon = c
				break
			}
		}
	}
	if coupon != nil {
		coupon.UsedBy = ride.ID
		ride.Discount = coupon.Discount
		persist("UPDATE coupons SET used_by = ? WHERE user_id = ? AND code = ?", ride.ID, u.ID, coupon.Code)
	}

	addStatus(ride, StMatching, now)
	s.Waiting = append(s.Waiting, ride)
	fare := ride.Fare()
	mu.Unlock()
	triggerMatch()

	writeJSON(w, http.StatusAccepted, &appPostRidesResponse{RideID: rideID, Fare: fare})
}

type appPostRidesEstimatedFareResponse struct {
	Fare     int `json:"fare"`
	Discount int `json:"discount"`
}

func appPostRidesEstimatedFare(w http.ResponseWriter, r *http.Request, u *User) {
	req := &appPostRidesRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.PickupCoordinate == nil || req.DestinationCoordinate == nil {
		writeError(w, http.StatusBadRequest, errors.New("required fields(pickup_coordinate, destination_coordinate) are empty"))
		return
	}
	discount := 0
	mu.Lock()
	found := false
	for _, c := range u.Coupons {
		if c.Code == "CP_NEW2024" && c.UsedBy == "" {
			discount = c.Discount
			found = true
			break
		}
	}
	if !found {
		for _, c := range u.Coupons {
			if c.UsedBy == "" {
				discount = c.Discount
				break
			}
		}
	}
	mu.Unlock()
	p, d := req.PickupCoordinate, req.DestinationCoordinate
	metered := farePerDistance * calculateDistance(p.Latitude, p.Longitude, d.Latitude, d.Longitude)
	discounted := initialFare + max(metered-discount, 0)
	writeJSON(w, http.StatusOK, &appPostRidesEstimatedFareResponse{
		Fare:     discounted,
		Discount: calculateFare(p.Latitude, p.Longitude, d.Latitude, d.Longitude) - discounted,
	})
}

