package main

import (
	"bytes"
	"context"
	"fmt"
	"io"
	"log"
	"net/http"
	"strconv"
	"time"
)

var paymentClient = &http.Client{
	Transport: &http.Transport{
		MaxIdleConns:        512,
		MaxIdleConnsPerHost: 512,
		IdleConnTimeout:     90 * time.Second,
	},
	Timeout: 5 * time.Second,
}

// requestPayment posts a payment, retrying with the same Idempotency-Key
// until the gateway acknowledges it.
func requestPayment(ctx context.Context, url, token, rideID string, amount int) error {
	body := []byte(`{"amount":` + strconv.Itoa(amount) + `}`)
	deadline := time.Now().Add(9 * time.Second)
	var lastErr error
	for attempt := 0; ; attempt++ {
		req, err := http.NewRequest(http.MethodPost, url+"/payments", bytes.NewReader(body))
		if err != nil {
			return err
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Authorization", "Bearer "+token)
		req.Header.Set("Idempotency-Key", rideID)
		res, err := paymentClient.Do(req)
		if err == nil {
			io.Copy(io.Discard, res.Body)
			res.Body.Close()
			if res.StatusCode == http.StatusNoContent || res.StatusCode == http.StatusOK {
				return nil
			}
			lastErr = fmt.Errorf("payment status %d", res.StatusCode)
		} else {
			lastErr = err
		}
		if time.Now().After(deadline) {
			log.Printf("payment give up ride=%s: %v", rideID, lastErr)
			return lastErr
		}
		time.Sleep(time.Duration(min(10*(attempt+1), 100)) * time.Millisecond)
	}
}

