cat > main.go <<'EOF'
package main

import (
	"bufio"
	"bytes"
	"crypto/tls"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"log"
	"math/rand"
	"net/http"
	"net/http/cookiejar"
	"strings"
	"sync"
	"sync/atomic"
	"time"
)

var base = flag.String("base", "https://isuride.xiv.isucon.net", "")
var nChairs = flag.Int("chairs", 10, "")
var nUsers = flag.Int("users", 10, "")
var dur = flag.Duration("dur", 20*time.Second, "")
var doInit = flag.Bool("init", true, "")
var payURL = flag.String("pay", "http://localhost:12345", "")

var errs int64

func fail(format string, a ...any) {
	atomic.AddInt64(&errs, 1)
	log.Printf("FAIL: "+format, a...)
}

type client struct {
	hc *http.Client
}

func newClient() *client {
	jar, _ := cookiejar.New(nil)
	return &client{hc: &http.Client{Jar: jar, Transport: &http.Transport{TLSClientConfig: &tls.Config{}, MaxIdleConnsPerHost: 10}}}
}

func (c *client) do(method, path string, body any, out any) int {
	var rd io.Reader
	if body != nil {
		b, _ := json.Marshal(body)
		rd = bytes.NewReader(b)
	}
	req, _ := http.NewRequest(method, *base+path, rd)
	req.Header.Set("Content-Type", "application/json")
	res, err := c.hc.Do(req)
	if err != nil {
		fail("%s %s: %v", method, path, err)
		return 0
	}
	defer res.Body.Close()
	b, _ := io.ReadAll(res.Body)
	if out != nil && len(b) > 0 {
		if err := json.Unmarshal(b, out); err != nil {
			fail("%s %s decode: %v %s", method, path, err, b)
		}
	}
	return res.StatusCode
}

type Coord struct {
	Latitude  int `json:"latitude"`
	Longitude int `json:"longitude"`
}

type Notif struct {
	RideID string `json:"ride_id"`
	Status string `json:"status"`
	Pickup Coord  `json:"pickup_coordinate"`
	Dest   Coord  `json:"destination_coordinate"`
	Fare   int    `json:"fare"`
	Chair  *struct {
		ID    string `json:"id"`
		Stats struct {
			Count int     `json:"total_rides_count"`
			Avg   float64 `json:"total_evaluation_avg"`
		} `json:"stats"`
	} `json:"chair"`
	User *struct {
		ID   string `json:"id"`
		Name string `json:"name"`
	} `json:"user"`
}

func (c *client) sse(path string, ch chan<- Notif, stop <-chan struct{}) {
	req, _ := http.NewRequest("GET", *base+path, nil)
	res, err := c.hc.Do(req)
	if err != nil {
		fail("sse %s: %v", path, err)
		return
	}
	if !strings.HasPrefix(res.Header.Get("Content-Type"), "text/event-stream") {
		fail("sse content-type %s", res.Header.Get("Content-Type"))
	}
	go func() { <-stop; res.Body.Close() }()
	sc := bufio.NewScanner(res.Body)
	for sc.Scan() {
		line := sc.Text()
		if line == "" {
			continue
		}
		if !strings.HasPrefix(line, "data: ") {
			fail("bad sse line %q", line)
			continue
		}
		var n Notif
		if err := json.Unmarshal([]byte(line[6:]), &n); err != nil {
			fail("sse json %v", err)
			continue
		}
		ch <- n
	}
	close(ch)
}

var order = map[string]int{"MATCHING": 0, "ENROUTE": 1, "PICKUP": 2, "CARRYING": 3, "ARRIVED": 4, "COMPLETED": 5}

// checker validates a stream of notifications follows the state machine.
type checker struct {
	name   string
	ride   string
	status string
}

func (k *checker) feed(n Notif) {
	if n.RideID != k.ride {
		if k.ride != "" && k.status != "COMPLETED" {
			fail("%s: new ride %s before previous %s completed (was %s)", k.name, n.RideID, k.ride, k.status)
		}
		if n.Status != "MATCHING" {
			fail("%s: new ride %s starts with %s", k.name, n.RideID, n.Status)
		}
		k.ride, k.status = n.RideID, n.Status
		return
	}
	d := order[n.Status] - order[k.status]
	if d != 0 && d != 1 {
		fail("%s: ride %s transition %s -> %s", k.name, n.RideID, k.status, n.Status)
	}
	k.status = n.Status
}

var models = []struct {
	name  string
	speed int
}{{"リラックスシート NEO", 2}, {"エルゴクレスト II", 3}, {"アルティマシート X", 5}, {"ナイトシート ブラックエディション", 7}}

var totalMoved int64
var totalPaid sync.Map

func main() {
	flag.Parse()
	log.SetFlags(log.Lmicroseconds)
	admin := newClient()
	if *doInit {
		var r map[string]string
		if st := admin.do("POST", "/api/initialize", map[string]string{"payment_server": *payURL}, &r); st != 200 {
			log.Fatalf("init %d", st)
		}
	}
	stop := make(chan struct{})
	var wg sync.WaitGroup

	// owner + chairs
	oc := newClient()
	var ownerRes struct {
		ID    string `json:"id"`
		Token string `json:"chair_register_token"`
	}
	oname := fmt.Sprintf("testowner%d", time.Now().UnixNano())
	if st := oc.do("POST", "/api/owner/owners", map[string]string{"name": oname}, &ownerRes); st != 201 {
		log.Fatalf("owner %d", st)
	}
	chairDist := make([]int64, *nChairs)
	for i := 0; i < *nChairs; i++ {
		i := i
		cc := newClient()
		m := models[i%len(models)]
		var cr struct{ ID string `json:"id"` }
		if st := cc.do("POST", "/api/chair/chairs", map[string]string{"name": fmt.Sprintf("C%d", i), "model": m.name, "chair_register_token": ownerRes.Token}, &cr); st != 201 {
			log.Fatalf("chair %d", st)
		}
		pos := Coord{rand.Intn(100) - 50, rand.Intn(100) - 50}
		var rec map[string]int64
		if st := cc.do("POST", "/api/chair/coordinate", pos, &rec); st != 200 {
			fail("coord %d", st)
		}
		if st := cc.do("POST", "/api/chair/activity", map[string]bool{"is_active": true}, nil); st != 204 {
			fail("activity %d", st)
		}
		wg.Add(1)
		go func() {
			defer wg.Done()
			ch := make(chan Notif, 100)
			go cc.sse("/api/chair/notification", ch, stop)
			k := &checker{name: "chair" + cr.ID}
			move := func(to Coord, until func() bool) {
				for pos != to {
					step := m.speed
					for step > 0 && pos != to {
						if pos.Latitude != to.Latitude {
							if pos.Latitude < to.Latitude {
								pos.Latitude++
							} else {
								pos.Latitude--
							}
						} else if pos.Longitude < to.Longitude {
							pos.Longitude++
						} else {
							pos.Longitude--
						}
						step--
						chairDist[i]++
						atomic.AddInt64(&totalMoved, 1)
					}
					if st := cc.do("POST", "/api/chair/coordinate", pos, nil); st != 200 {
						fail("coord %d", st)
					}
					time.Sleep(20 * time.Millisecond)
				}
			}
			for n := range ch {
				k.feed(n)
				if n.User == nil {
					fail("chair notif without user")
				}
				switch n.Status {
				case "MATCHING":
					if st := cc.do("POST", "/api/chair/rides/"+n.RideID+"/status", map[string]string{"status": "ENROUTE"}, nil); st != 204 {
						fail("enroute %d", st)
					}
					move(n.Pickup, nil)
				case "PICKUP":
					if st := cc.do("POST", "/api/chair/rides/"+n.RideID+"/status", map[string]string{"status": "CARRYING"}, nil); st != 204 {
						fail("carrying %d", st)
					}
					move(n.Dest, nil)
				}
			}
		}()
	}

	// users
	var invCode string
	var completed int64
	for i := 0; i < *nUsers; i++ {
		uc := newClient()
		body := map[string]any{"username": fmt.Sprintf("u%d_%d", time.Now().UnixNano(), i), "firstname": "F", "lastname": "L", "date_of_birth": "2000-01-01"}
		if i > 0 && i <= 3 {
			body["invitation_code"] = invCode
		}
		var ur struct {
			ID   string `json:"id"`
			Code string `json:"invitation_code"`
		}
		if st := uc.do("POST", "/api/app/users", body, &ur); st != 201 {
			log.Fatalf("user %d", st)
		}
		if i == 0 {
			invCode = ur.Code
		}
		token := fmt.Sprintf("tok%d_%d", time.Now().UnixNano(), i)
		if st := uc.do("POST", "/api/app/payment-methods", map[string]string{"token": token}, nil); st != 204 {
			fail("paymethod %d", st)
		}
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			ch := make(chan Notif, 100)
			go uc.sse("/api/app/notification", ch, stop)
			k := &checker{name: "user" + ur.ID}
			deadline := time.Now().Add(*dur)
			sum := 0
			newRide := func() string {
				p := Coord{rand.Intn(100) - 50, rand.Intn(100) - 50}
				d := Coord{rand.Intn(100) - 50, rand.Intn(100) - 50}
				var est struct{ Fare, Discount int }
				uc.do("POST", "/api/app/rides/estimated-fare", map[string]Coord{"pickup_coordinate": p, "destination_coordinate": d}, &est)
				var nb struct {
					Chairs []any `json:"chairs"`
				}
				uc.do("GET", fmt.Sprintf("/api/app/nearby-chairs?latitude=%d&longitude=%d&distance=50", p.Latitude, p.Longitude), nil, &nb)
				var rr struct {
					RideID string `json:"ride_id"`
					Fare   int    `json:"fare"`
				}
				if st := uc.do("POST", "/api/app/rides", map[string]Coord{"pickup_coordinate": p, "destination_coordinate": d}, &rr); st != 202 {
					fail("ride %d", st)
				}
				if rr.Fare != est.Fare {
					fail("fare mismatch est=%d ride=%d", est.Fare, rr.Fare)
				}
				// second ride must conflict
				if st := uc.do("POST", "/api/app/rides", map[string]Coord{"pickup_coordinate": p, "destination_coordinate": d}, nil); st != 409 {
					fail("expected 409 got %d", st)
				}
				return rr.RideID
			}
			cur := newRide()
			var lastFare int
			for n := range ch {
				k.feed(n)
				if n.RideID != cur && n.Status != "COMPLETED" && n.Status != "ARRIVED" {
					// stale snapshot of older ride is fine only at start
				}
				lastFare = n.Fare
				switch n.Status {
				case "ARRIVED":
					if n.RideID == cur {
						var er struct{ CompletedAt int64 `json:"completed_at"` }
						if st := uc.do("POST", "/api/app/rides/"+n.RideID+"/evaluation", map[string]int{"evaluation": 1 + rand.Intn(5)}, &er); st != 200 {
							fail("eval %d", st)
						}
						sum += lastFare
					}
				case "COMPLETED":
					if n.RideID == cur {
						atomic.AddInt64(&completed, 1)
						if n.Chair == nil || n.Chair.Stats.Count == 0 {
							fail("completed notif without stats")
						}
						if time.Now().Before(deadline) {
							cur = newRide()
						} else {
							totalPaid.Store(token, sum)
							var rides struct {
								Rides []struct {
									ID   string `json:"id"`
									Fare int    `json:"fare"`
								} `json:"rides"`
							}
							uc.do("GET", "/api/app/rides", nil, &rides)
							s2 := 0
							for _, r := range rides.Rides {
								s2 += r.Fare
							}
							if s2 != sum {
								fail("app rides fare sum %d != %d", s2, sum)
							}
							return
						}
					}
				}
			}
		}(i)
	}
	done := make(chan struct{})
	go func() { wg.Wait(); close(done) }()
	userDone := make(chan struct{})
	_ = userDone
	select {
	case <-done:
	case <-time.After(*dur + 40*time.Second):
		fail("timeout waiting for flows")
	}
	close(stop)
	time.Sleep(500 * time.Millisecond)

	// verify payments via mock
	totalPaid.Range(func(k, v any) bool {
		req, _ := http.NewRequest("GET", *payURL+"/payments", nil)
		req.Header.Set("Authorization", "Bearer "+k.(string))
		res, err := http.DefaultClient.Do(req)
		if err != nil {
			fail("pay get %v", err)
			return true
		}
		var ps []struct{ Amount int }
		json.NewDecoder(res.Body).Decode(&ps)
		res.Body.Close()
		s := 0
		for _, p := range ps {
			s += p.Amount
		}
		if s != v.(int) {
			fail("payments %d != fares %d (n=%d)", s, v.(int), len(ps))
		}
		return true
	})
	var oc2 struct {
		Chairs []struct {
			ID   string `json:"id"`
			Name string `json:"name"`
			Dist int    `json:"total_distance"`
		} `json:"chairs"`
	}
	time.Sleep(200 * time.Millisecond)
	oc.do("GET", "/api/owner/chairs", nil, &oc2)
	var dsum int
	for _, c := range oc2.Chairs {
		dsum += c.Dist
	}
	var sales struct {
		Total int `json:"total_sales"`
	}
	oc.do("GET", "/api/owner/sales", nil, &sales)
	log.Printf("completed rides=%d moved=%d ownerDist=%d sales=%d errors=%d", completed, totalMoved, dsum, sales.Total, atomic.LoadInt64(&errs))
}
