func (s *State) match(now time.Time) {
	free := make([]*Chair, 0, 64)
	for _, c := range s.ChairList {
		if c.isFree() {
			c.Reserved = false
			free = append(free, c)
		} else if c.Reserved {
			c.Reserved = false
		}
	}
	if len(s.Waiting) == 0 || len(free) == 0 {
		return
	}
	rides := s.Waiting
	usedR := make([]bool, len(rides))
	assignedR := make([]bool, len(rides))
	usedC := make([]bool, len(free))
	cost := func(r *Ride, c *Chair) float64 {
		d := calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
		return float64(d) / float64(c.Speed)
	}
	assigned := 0
	deferred := false
	take := func(ri, ci int) {
		usedR[ri], usedC[ci] = true, true
		c := free[ci]
		if now.Sub(c.ListedAt) < listCooldown {
			// a nearby-chairs response listing this chair may still be in flight
			c.Reserved = true
			deferred = true
			return
		}
		assignedR[ri] = true
		assigned++
		s.assign(rides[ri], c, now)
	}

	// urgent rides first: oldest first, best chair in the same region
	for ri, r := range rides {
		wait := now.Sub(r.CreatedAt)
		if wait < urgentWait {
			break
		}
		best := -1
		bestCost := 0.0
		for ci, c := range free {
			if usedC[ci] {
				continue
			}
			d := calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
			if d > maxNormalDist && wait < crossRegionWait {
				continue
			}
			cc := cost(r, c)
			if best < 0 || cc < bestCost {
				best, bestCost = ci, cc
			}
		}
		if best >= 0 {
			statUrgent++
			take(ri, best)
		}
	}

	pairs := make([]matchPair, 0, 256)
	for ri, r := range rides {
		if usedR[ri] {
			continue
		}
		for ci, c := range free {
			if usedC[ci] {
				continue
			}
