package main

import (
	"sort"
	"sync/atomic"
	"time"
)

var matchSig = make(chan struct{}, 1)

func triggerMatch() {
	select {
	case matchSig <- struct{}{}:
	default:
	}
}

const (
	matchInterval   = 50 * time.Millisecond
	urgentWait      = 20 * time.Second // oldest-first within region after this
	crossRegionWait = 40 * time.Second // allow any distance after this
	maxNormalDist   = 400
	listCooldown    = 100 * time.Millisecond // don't assign a chair within this long after nearby listed it
	completedGrace  = 100 * time.Millisecond // hide a chair from nearby this long after its COMPLETED was delivered
)

var retryScheduled int32

func matcherLoop() {
	t := time.NewTicker(matchInterval)
	defer t.Stop()
	for {
		select {
		case <-t.C:
		case <-matchSig:
		}
		t0 := time.Now()
		mu.Lock()
		if st != nil {
			st.match(nowUS())
		}
		mu.Unlock()
		atomic.AddInt64(&statMatchNs, int64(time.Since(t0)))
		atomic.AddInt64(&statMatchCalls, 1)
	}
}

func (c *Chair) isFree() bool {
	if !c.IsActive || !c.HasLoc {
		return false
	}
	if c.Current == nil {
		return true
	}
	return c.Current.Latest() == StCompleted && c.Delivered
}

type matchPair struct {
	ri, ci int
	cost   float64
}

// match assigns free chairs to waiting rides. mu held.
func (s *State) match(now time.Time) {
	free := make([]*Chair, 0, 64)
	for _, c := range s.ChairList {
		if c.isFree() {
			c.Reserved = false
			free = append(free, c)
		} else if c.Reserved {
			c.Reserved = false
		}
	}
	if len(s.Waiting) == 0 || len(free) == 0 {
		return
	}
	rides := s.Waiting
	usedR := make([]bool, len(rides))
	assignedR := make([]bool, len(rides))
	usedC := make([]bool, len(free))
	// eff is the expected score per chair tick of serving r with c.
	eff := func(r *Ride, c *Chair, pickup int) float64 {
		dist := float64(calculateDistance(r.PickupLat, r.PickupLon, r.DestLat, r.DestLon))
		ticks := (float64(pickup)+dist)/float64(c.Speed) + overheadTicks
		return (dist + 0.1*float64(pickup) + 5) / ticks
	}
	assigned := 0
	deferred := false
	take := func(ri, ci int) {
		usedR[ri], usedC[ci] = true, true
		c := free[ci]
		if now.Sub(c.ListedAt) < listCooldown {
			// a nearby-chairs response listing this chair may still be in flight
			c.Reserved = true
			deferred = true
			return
		}
		assignedR[ri] = true
		assigned++
		s.assign(rides[ri], c, now)
	}

	// urgent rides first: oldest first, best chair in the same region
	for ri, r := range rides {
		wait := now.Sub(r.CreatedAt)
		if wait < urgentWait {
			break
		}
		best := -1
		bestCost := 0.0
		for ci, c := range free {
			if usedC[ci] {
				continue
			}
			d := calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
			if d > maxNormalDist && wait < crossRegionWait {
				continue
			}
			cc := -eff(r, c, d)
			if best < 0 || cc < bestCost {
				best, bestCost = ci, cc
			}
		}
		if best >= 0 {
			statUrgent++
			take(ri, best)
		}
	}

	pairs := make([]matchPair, 0, 256)
	for ri, r := range rides {
		if usedR[ri] {
			continue
		}
		for ci, c := range free {
			if usedC[ci] {
				continue
			}
			d := calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon)
			if d > maxNormalDist {
				continue
			}
			pairs = append(pairs, matchPair{ri, ci, -(eff(r, c, d) + waitBonus*now.Sub(r.CreatedAt).Seconds())})
		}
	}
	sort.Slice(pairs, func(i, j int) bool {
		if pairs[i].cost != pairs[j].cost {
			return pairs[i].cost < pairs[j].cost
		}
		return pairs[i].ri < pairs[j].ri
	})
	for _, p := range pairs {
		if usedR[p.ri] || usedC[p.ci] {
			continue
		}
		take(p.ri, p.ci)
	}

	if assigned > 0 {
		rest := make([]*Ride, 0, len(rides)-assigned)
		for ri, r := range rides {
			if !assignedR[ri] {
				rest = append(rest, r)
			}
		}
		s.Waiting = rest
	}
	if deferred && atomic.CompareAndSwapInt32(&retryScheduled, 0, 1) {
		time.AfterFunc(listCooldown+5*time.Millisecond, func() {
			atomic.StoreInt32(&retryScheduled, 0)
			triggerMatch()
		})
	}
}

func (s *State) assign(r *Ride, c *Chair, now time.Time) {
	atomic.AddInt64(&statAssigned, 1)
	statPickupDist += int64(calculateDistance(c.Lat, c.Lon, r.PickupLat, r.PickupLon))
	statWaitNs += int64(now.Sub(r.CreatedAt))
	r.Chair = c
	r.UpdatedAt = now
	c.Current = r
	c.Delivered = false
	c.Reserved = false
	c.Rides = append(c.Rides, r)
	persist("UPDATE rides SET chair_id = ?, updated_at = ? WHERE id = ?", c.ID, now, r.ID)
	c.notif.push(chairEvent(r, StMatching))
}

